def transform(grid):
    out = [row[:] for row in grid]
    rows = [r for r in range(len(grid)) if 5 in grid[r]]
    cols = [c for c in range(len(grid[0])) if any(grid[r][c] == 5 for r in range(len(grid)))]
    top, bottom = min(rows), max(rows)
    left, right = min(cols), max(cols)

    mid_r = (top + bottom) // 2
    mid_c = (left + right) // 2

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            color = grid[r][c]
            if color == 0 or color == 5:
                continue

            # Determine which outer corner the colored marker indicates.
            vertical = "top" if r < top else "bottom"
            horizontal = "left" if c < left else "right"
            corners = {(vertical, horizontal), (
                "bottom" if vertical == "top" else "top",
                "right" if horizontal == "left" else "left"
            )}

            for rr in range(top + 1, bottom):
                for cc in range(left + 1, right):
                    quadrant = ("top" if rr <= mid_r else "bottom",
                                "left" if cc <= mid_c else "right")
                    if quadrant in corners:
                        out[rr][cc] = color

    return out
